import{_ as p,r as a,o,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const h=JSON.parse('{"title":"{% for %} - October CMS - 3.x","titleTemplate":false,"description":"Twig 标签","frontmatter":{"subtitle":"Twig 标签"},"headers":[{"level":2,"title":"遍历集合","slug":"遍历集合","link":"#遍历集合","children":[]},{"level":2,"title":"添加条件","slug":"添加条件","link":"#添加条件","children":[]},{"level":2,"title":"循环变量","slug":"循环变量","link":"#循环变量","children":[]}],"relativePath":"3.x/zh-cn/markup/tag/for.md","filePath":"3.x/zh-cn/markup/tag/for.md"}'),u={name:"3.x/zh-cn/markup/tag/for.md"};function g(r,n,k,d,m,w){const t=a("pre-heading"),e=a("post-heading");return o(),l("div",null,[s(t),n[0]||(n[0]=c("h1",null,"{% for %}",-1)),s(e),n[1]||(n[1]=i(`<p><code>{% for %}</code> 和 <code>{% endfor %}</code> 标签将遍历集合中的每个值。集合可以是数组或实现了 <code>Traversable</code> 接口的对象。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>你也可以同时访问键和值：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> key<span class="token punctuation">,</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> key <span class="token delimiter punctuation">}}</span></span>: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>如果集合为空，你可以使用 else 渲染一个替代块：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>em</span><span class="token punctuation">&gt;</span></span>There are no users found<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>em</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="遍历集合"><a href="#遍历集合" class="header-anchor">#</a> 遍历集合</h2><p>如果你需要遍历一组数字，可以使用 <code>..</code> 运算符：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> i <span class="token operator">in</span> <span class="token number">0.</span><span class="token number">.10</span> <span class="token delimiter punctuation">%}</span></span>
    - <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> i <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>上面的代码片段将打印从 0 到 10 的所有数字。</p><p>它也可以用于字母：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> letter <span class="token operator">in</span> <span class="token string"><span class="token punctuation">&#39;</span>a<span class="token punctuation">&#39;</span></span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token string"><span class="token punctuation">&#39;</span>z<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
    - <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> letter <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><code>..</code> 运算符两侧可以使用任何表达式：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> letter <span class="token operator">in</span> <span class="token string"><span class="token punctuation">&#39;</span>a<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>upper<span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token string"><span class="token punctuation">&#39;</span>z<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>upper <span class="token delimiter punctuation">%}</span></span>
    - <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> letter <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="添加条件"><a href="#添加条件" class="header-anchor">#</a> 添加条件</h2><p>与 PHP 不同，循环中没有 <code>break</code> 或 <code>continue</code> 函数，但你仍然可以过滤集合。以下示例跳过所有未激活的 <code>users</code>。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> user<span class="token punctuation">.</span>active <span class="token delimiter punctuation">%}</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="循环变量"><a href="#循环变量" class="header-anchor">#</a> 循环变量</h2><p>在 <code>for</code> 循环块内部，你可以访问一些特殊变量：</p><div class="table"><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>loop.index</code></td><td>当前循环迭代次数（从 1 开始）</td></tr><tr><td><code>loop.index0</code></td><td>当前循环迭代次数（从 0 开始）</td></tr><tr><td><code>loop.revindex</code></td><td>距循环结束的迭代次数（从 1 开始）</td></tr><tr><td><code>loop.revindex0</code></td><td>距循环结束的迭代次数（从 0 开始）</td></tr><tr><td><code>loop.first</code></td><td>如果是第一次迭代则为 true</td></tr><tr><td><code>loop.last</code></td><td>如果是最后一次迭代则为 true</td></tr><tr><td><code>loop.length</code></td><td>集合中的元素数量</td></tr><tr><td><code>loop.parent</code></td><td>父级上下文</td></tr></tbody></table></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> loop<span class="token punctuation">.</span>index <span class="token delimiter punctuation">}}</span></span> - <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div>`,21))])}const v=p(u,[["render",g]]);export{h as __pageData,v as default};
